// Dependency-free XLSX reader. ZIP central directory + browser-native DEFLATE.
export async function readXLSX(buffer){const bytes=new Uint8Array(buffer),v=new DataView(buffer),decoder=new TextDecoder();let end=bytes.length-22;while(end>=Math.max(0,bytes.length-65557)&&v.getUint32(end,true)!==0x06054b50)end--;if(end<0)throw Error('올바른 Excel .xlsx 파일이 아닙니다.');const entries=new Map();let pos=v.getUint32(end+16,true);for(let n=0;n<v.getUint16(end+10,true);n++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('손상된 ZIP 구조');const method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),expanded=v.getUint32(pos+24,true),nl=v.getUint16(pos+28,true),el=v.getUint16(pos+30,true),cl=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true);if(expanded>20000000)throw Error('압축 해제 파일이 너무 큽니다.');const name=decoder.decode(bytes.slice(pos+46,pos+46+nl));entries.set(name,{method,size,offset});pos+=46+nl+el+cl;}async function xml(name){const e=entries.get(name);if(!e)return null;const p=e.offset+30+v.getUint16(e.offset+26,true)+v.getUint16(e.offset+28,true),data=bytes.slice(p,p+e.size);let out;if(e.method===0)out=data;else if(e.method===8)out=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());else throw Error('지원하지 않는 Excel 압축 형식');const doc=new DOMParser().parseFromString(decoder.decode(out),'application/xml');if(doc.querySelector('parsererror'))throw Error('Excel XML이 손상되었습니다.');return doc;}
const workbook=await xml('xl/workbook.xml'),rels=await xml('xl/_rels/workbook.xml.rels');const sheet=workbook?.getElementsByTagName('sheet')[0],rid=sheet?.getAttribute('r:id');const rel=Array.from(rels?.getElementsByTagName('Relationship')||[]).find(r=>r.getAttribute('Id')===rid);let target=rel?.getAttribute('Target')||'worksheets/sheet1.xml';target=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');const shared=await xml('xl/sharedStrings.xml');const strings=Array.from(shared?.getElementsByTagName('si')||[]).map(si=>Array.from(si.getElementsByTagName('t')).map(t=>t.textContent).join(''));const doc=await xml(target);if(!doc)throw Error('첫 번째 시트를 찾을 수 없습니다.');return Array.from(doc.getElementsByTagName('row')).map(r=>{const row=[];for(const c of r.getElementsByTagName('c')){const ref=c.getAttribute('r')||'A1';let idx=0;for(const char of ref.replace(/\d/g,''))idx=idx*26+char.charCodeAt(0)-64;const type=c.getAttribute('t');const value=c.getElementsByTagName('v')[0]?.textContent||'';row[idx-1]=type==='s'?strings[+value]:type==='inlineStr'?Array.from(c.getElementsByTagName('t')).map(t=>t.textContent).join(''):value;}return row;});}
